//! Ce que chaque fiche dit d'elle-même, en données plutôt qu'en phrases.
//!
//! Les monographies répondent à « que dois-je savoir sur ce médicament ».
//! Ce module répond à l'autre moitié, celle qu'un paragraphe ne sait pas
//! rendre : « quels médicaments ont telle propriété ». On ne trie pas des
//! phrases ; on trie des nombres et des énumérations.
//!
//! **Une facette est adossée à ce que la fiche écrit.** Si la monographie
//! ne chiffre pas la demi-vie, la facette dit qu'elle n'est pas chiffrée —
//! elle n'invente pas un nombre que personne ne pourrait relire. C'est ce
//! qui permet de corriger une facette en corrigeant la fiche, et non deux
//! contenus qui dérivent l'un de l'autre. Deux tests le tiennent, un par
//! versant, et ils ne lisent pas le même vocabulaire : un « altère » se
//! relit sur les mots de la lésion, un « traite » sur ceux de
//! l'indication. La lévothyroxine ne dit jamais « dysthyroïdie ».
//!
//! **Le champ d'où vient une phrase décide de ce qu'elle vaut.**
//! « Insuffisance rénale » dans les contre-indications décrit un rein
//! déjà malade dont dépend la dose — le rein commande le médicament ;
//! dans les effets indésirables, un rein que le médicament abîme. Seul
//! le second est un impact, et un médicament éliminé par le rein n'est
//! pas un médicament néphrotoxique.
//!
//! **Le grade ne veut pas dire la même chose des deux côtés** : gravité
//! sur « altère », centralité sur « traite ». Sans quoi soixante
//! antihypertenseurs noieraient les six médicaments de l'insuffisance
//! cardiaque sur l'axe du cœur.
//!
//! Statique, pur et testé, comme le calendrier vaccinal et les règles de
//! biologie. Aucun egui ici : la vue ne fait que trier et peindre — et
//! l'index se construit une fois, jamais dans la boucle de dessin.

/// Pourquoi une fiche n'a pas de demi-vie plasmatique exploitable.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Unknown {
    /// La notion n'a pas de sens : produit non absorbé, action locale,
    /// ion physiologique, vaccin.
    SansObjet,
    /// La notion a un sens mais la monographie ne la chiffre pas — une
    /// demi-vie « courte », « très longue », ou seulement tissulaire.
    NonChiffree,
}

impl Unknown {
    pub fn label(self) -> &'static str {
        match self {
            Unknown::SansObjet => "sans objet",
            Unknown::NonChiffree => "non chiffrée",
        }
    }
}

/// La demi-vie **plasmatique** de la fiche, en heures.
///
/// Volontairement distincte de ce qui dure au-delà : un bisphosphonate a
/// une demi-vie plasmatique de quelques heures et une rétention osseuse
/// de plusieurs années, et confondre les deux met Fosamax en tête d'un
/// classement où il n'a rien à faire. Ce qui dure au-delà est dans
/// [`Facets::beyond`].
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum HalfLife {
    /// Bornes basse et haute, en heures. Égales si la fiche donne un point.
    Hours { low: f32, high: f32 },
    /// Pas de demi-vie plasmatique exploitable, et pourquoi.
    None(Unknown),
}

impl HalfLife {
    /// La valeur sur laquelle on trie : la borne haute, ou rien.
    pub fn sort_key(self) -> Option<f32> {
        match self {
            HalfLife::Hours { high, .. } => Some(high),
            HalfLife::None(_) => None,
        }
    }

    /// Écrit dans l'unité qui se lit : minutes, heures ou jours.
    pub fn label(self) -> String {
        let (low, high) = match self {
            HalfLife::None(u) => return u.label().to_owned(),
            HalfLife::Hours { low, high } => (low, high),
        };
        let unit = |v: f32| -> (f32, &'static str) {
            if v < 1.0 / 60.0 {
                (v * 3600.0, "s")
            } else if v < 1.0 {
                (v * 60.0, "min")
            } else if v < 72.0 {
                (v, "h")
            } else {
                (v / 24.0, "j")
            }
        };
        let (a, ua) = unit(low);
        let (b, ub) = unit(high);
        let n = |v: f32| {
            if v >= 10.0 {
                format!("{}", v.round() as i64)
            } else {
                format!("{v:.1}").replace('.', ",")
            }
        };
        if (high - low).abs() < f32::EPSILON {
            format!("{} {ua}", n(a))
        } else if ua == ub {
            format!("{} à {} {ub}", n(a), n(b))
        } else {
            format!("{} {ua} à {} {ub}", n(a), n(b))
        }
    }
}

/// L'organe ou le système sur lequel une fiche pèse.
///
/// L'énumération est plus large que ce qui est peuplé : ajouter un axe ne
/// doit pas obliger à retoucher le type ni la vue.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Organ {
    Thyroide,
    Coeur,
    Foie,
    Rein,
    Moelle,
    Oeil,
    Os,
    Poumon,
    Neuro,
    Peau,
    Digestif,
    Oreille,
}

impl Organ {
    pub const ALL: &'static [Organ] = &[
        Organ::Thyroide,
        Organ::Coeur,
        Organ::Foie,
        Organ::Rein,
        Organ::Moelle,
        Organ::Oeil,
        Organ::Os,
        Organ::Poumon,
        Organ::Neuro,
        Organ::Peau,
        Organ::Digestif,
        Organ::Oreille,
    ];

    pub fn label(self) -> &'static str {
        match self {
            Organ::Thyroide => "Thyroïde",
            Organ::Coeur => "Cœur",
            Organ::Foie => "Foie",
            Organ::Rein => "Rein",
            Organ::Moelle => "Moelle",
            Organ::Oeil => "Œil",
            Organ::Os => "Os",
            Organ::Poumon => "Poumon",
            Organ::Neuro => "Neurologique",
            Organ::Peau => "Peau",
            Organ::Digestif => "Digestif",
            Organ::Oreille => "Oreille",
        }
    }
}

/// Dans quel sens la fiche touche l'organe.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Effect {
    /// C'est l'organe visé par le traitement.
    Traite,
    /// C'est l'organe qui paie.
    Altere,
}

impl Effect {
    pub fn label(self) -> &'static str {
        match self {
            Effect::Traite => "traite",
            Effect::Altere => "altère",
        }
    }
}

/// À quel point.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Grade {
    /// Ce qui se sait.
    Mineur,
    /// Ce qui se surveille.
    Notable,
    /// Ce qui fait arrêter, ou surveiller de près.
    Majeur,
}

impl Grade {
    pub fn label(self) -> &'static str {
        match self {
            Grade::Mineur => "mineur",
            Grade::Notable => "notable",
            Grade::Majeur => "majeur",
        }
    }
}

/// Un organe, un sens, un degré, et la clause qui le justifie.
#[derive(Clone, Copy, Debug)]
pub struct Impact {
    pub organ: Organ,
    pub effect: Effect,
    pub grade: Grade,
    /// Une clause, pas un paragraphe : c'est ce que la colonne affiche.
    pub why: &'static str,
}

/// Tout ce que l'on sait d'une fiche, sous forme triable.
#[derive(Clone, Debug)]
pub struct Facets {
    pub name: &'static str,
    pub half_life: HalfLife,
    /// Ce qui dure au-delà du plasma : effet irréversible, dépôt,
    /// rétention tissulaire. Vide s'il n'y a rien à dire.
    pub beyond: &'static str,
    pub impacts: Vec<Impact>,
}

