    ///
    /// C'est la règle qui sépare cette table d'une liste écrite de
    /// mémoire. Deux impacts sur la thyroïde avaient été écrits pour des
    /// fiches dont la monographie ne dit rien de la thyroïde ; seule une
    /// confrontation systématique les a trouvés. Le test relit donc le
    /// texte de chaque fiche et exige d'y trouver le vocabulaire de
    /// l'organe.
    ///
    /// Ajouter un impact sur un vocabulaire absent de cette table est
    /// possible — il suffit d'ajouter le mot — mais c'est alors un geste
    /// délibéré, et non un oubli.
